// Secrets on the device (AI keys), sealed with AES-GCM before they're
// stored. The sealing key is generated by the browser as non-extractable and
// kept in IndexedDB: this page can use it, but nothing can read it out.
// Anyone who copies the database file, a backup or the profile gets only
// ciphertext. (Code running in the page itself could still use the key;
// that's what the content security policy is for.)

export type KeySource = () => Promise<CryptoKey>;

const b64 = (bytes: Uint8Array) => btoa(String.fromCharCode(...bytes));
const unb64 = (s: string) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

// Each sealed value is bound to `context` (e.g. the key's row id): moved
// onto another row, it no longer opens.
export async function sealSecret(key: CryptoKey, plain: string, context: string): Promise<string> {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = new Uint8Array(
    await crypto.subtle.encrypt({ name: "AES-GCM", iv, additionalData: new TextEncoder().encode(context) }, key, new TextEncoder().encode(plain)),
  );
  return `v1.${b64(iv)}.${b64(ct)}`;
}

export async function openSecret(key: CryptoKey, sealed: string, context: string): Promise<string> {
  const [v, iv, ct] = sealed.split(".");
  if (v !== "v1" || !iv || !ct) throw new Error("Not a sealed secret.");
  const plain = await crypto.subtle.decrypt({ name: "AES-GCM", iv: unb64(iv), additionalData: new TextEncoder().encode(context) }, key, unb64(ct));
  return new TextDecoder().decode(plain);
}

export const newSealingKey = () => crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]) as Promise<CryptoKey>;

// The browser's sealing key, created on first use and kept in IndexedDB.
export function indexedDbKeySource(dbName = "confu-device"): KeySource {
  let cached: Promise<CryptoKey> | null = null;
  return () =>
    (cached ??= new Promise<CryptoKey>((resolve, reject) => {
      const req = indexedDB.open(dbName, 1);
      req.onupgradeneeded = () => req.result.createObjectStore("keys");
      req.onerror = () => reject(req.error);
      req.onsuccess = () => {
        const db = req.result;
        const get = db.transaction("keys").objectStore("keys").get("sealing");
        get.onerror = () => reject(get.error);
        get.onsuccess = async () => {
          if (get.result) return resolve(get.result as CryptoKey);
          const key = await newSealingKey();
          const put = db.transaction("keys", "readwrite").objectStore("keys").put(key, "sealing");
          put.onerror = () => reject(put.error);
          put.onsuccess = () => resolve(key);
        };
      };
    }));
}
